# Day 41 Part 4: Serpentine PCB Enclosure Wraps & Differential Capacitance Matrix
import math

class EnclosureCapacitanceMatrix:
    """Models interdigitated serpentine electrode capacitance and drill-penetration detection."""
    def __init__(self, num_nodes: int = 4, nominal_c_pf: float = 18.5):
        self.num_nodes = num_nodes
        self.nominal_c = nominal_c_pf  # Nominal mutual capacitance in pF
        self.delta_threshold_pf = 1.2   # Trigger threshold for capacitive proximity intrusion

    def measure_node_capacitance(self, drill_proximity_mm: float, drill_dielectric: float = 1.0) -> list[float]:
        """Calculates capacitance matrix values when a conductive drill bit approaches the enclosure."""
        capacitances = []
        for i in range(self.num_nodes):
            # Proximity perturbation: C increases inversely with drill distance
            if drill_proximity_mm <= 0.0:
                perturbation = 25.0  # Physical contact/short circuit
            elif drill_proximity_mm < 3.0:
                perturbation = (3.0 - drill_proximity_mm) * 1.5 * drill_dielectric
            else:
                perturbation = 0.0
            capacitances.append(round(self.nominal_c + perturbation, 3))
        return capacitances

    def evaluate_matrix(self, measured_caps: list[float]) -> dict:
        tripped_nodes = []
        for idx, c in enumerate(measured_caps):
            delta = abs(c - self.nominal_c)
            if delta > self.delta_threshold_pf:
                tripped_nodes.append((idx, round(delta, 3)))

        tamper_detected = len(tripped_nodes) > 0
        return {
            'measured_capacitances_pf': measured_caps,
            'tripped_nodes': tripped_nodes,
            'tamper_detected': tamper_detected,
            'system_state': 'TAMPER_ALARM' if tamper_detected else 'SECURE_STANDBY'
        }

if __name__ == '__main__':
    matrix = EnclosureCapacitanceMatrix(num_nodes=4, nominal_c_pf=15.0)
    print("=== Serpentine Enclosure Differential Capacitance Monitor ===")
    scenarios = [
        ("Nominal Ambient State", 10.0),
        ("Approaching Drill Bit (1.5mm)", 1.5),
        ("Enclosure Puncture (0.0mm)", 0.0)
    ]
    for desc, dist in scenarios:
        caps = matrix.measure_node_capacitance(dist)
        res = matrix.evaluate_matrix(caps)
        print(f"Scenario: {desc:32s} -> Caps: {res['measured_capacitances_pf']} pF | Tripped: {len(res['tripped_nodes'])} | State: {res['system_state']}")

# Day 43 Part 3: BB-SRAM Hardware Crowbar Discharge Simulation & RC Time Constant
import math

class HardwareCrowbarDischargeCircuit:
    """Simulates active NMOS crowbar pulldown transistors discharging BB-SRAM bit storage nodes."""
    def __init__(self, r_nmos_on_ohms: float = 2.5, c_storage_cell_pf: float = 85.0):
        self.r_on = r_nmos_on_ohms  # Total channel resistance of parallel NMOS discharge network
        self.c_total = c_storage_cell_pf * 1e-12  # Total parasitic storage node capacitance
        self.tau_ns = (self.r_on * self.c_total) * 1e9  # RC time constant in nanoseconds

    def calculate_voltage_decay(self, initial_v: float, elapsed_time_ns: float) -> float:
        # V(t) = V_0 * exp(-t / (R * C))
        return initial_v * math.exp(-elapsed_time_ns / (self.tau_ns + 1e-15))

    def evaluate_discharge_curve(self, initial_voltage: float = 3.0) -> list[dict]:
        time_steps_ns = [0.0, 0.2, 0.5, 1.0, 2.0, 5.0]
        results = []
        v_safe_cutoff = 0.1  # When voltage drops below 100 mV, logic state is 100% erased
        for t in time_steps_ns:
            v_t = self.calculate_voltage_decay(initial_voltage, t)
            pct_erased = (1.0 - (v_t / initial_voltage)) * 100.0
            results.append({
                'time_ns': t,
                'voltage_v': round(v_t, 4),
                'percent_erased': round(pct_erased, 2),
                'state_destroyed': v_t < v_safe_cutoff
            })
        return results

if __name__ == '__main__':
    crowbar = HardwareCrowbarDischargeCircuit(r_nmos_on_ohms=2.0, c_storage_cell_pf=60.0)
    print("=== BB-SRAM Active NMOS Crowbar Discharge Profile ===")
    print(f"NMOS On-Resistance: {crowbar.r_on} Ohms | Node Capacitance: {crowbar.c_total*1e12:.1f} pF | RC Tau: {crowbar.tau_ns:.3f} ns")
    steps = crowbar.evaluate_discharge_curve(initial_voltage=3.0)
    for s in steps:
        print(f"Time: {s['time_ns']:4.1f} ns -> Node Voltage: {s['voltage_v']:6.4f} V | Erased: {s['percent_erased']:6.2f}% | Destroyed: {s['state_destroyed']}")

# Day 44 Part 4: Dynamic Debug Session Watchdog Timer & Ephemeral Token Expiry
import struct

class DebugSessionWatchdog:
    """Enforces hardware-enforced countdown timers and auto-relocking on debug ports."""
    def __init__(self, session_timeout_ms: int = 5000):
        self.timeout_ms = session_timeout_ms
        self.time_remaining_ms = session_timeout_ms
        self.session_active = False

    def start_session(self) -> None:
        self.session_active = True
        self.time_remaining_ms = self.timeout_ms

    def tick_ms(self, elapsed_ms: int) -> dict:
        if not self.session_active:
            return {'session_active': False, 'time_left_ms': 0, 'status': 'LOCKED'}

        self.time_remaining_ms = max(0, self.time_remaining_ms - elapsed_ms)
        if self.time_remaining_ms == 0:
            self.session_active = False  # Hard auto-relock in hardware

        return {
            'session_active': self.session_active,
            'time_left_ms': self.time_remaining_ms,
            'status': 'SESSION_ACTIVE' if self.session_active else 'TIMEOUT_AUTO_RELOCKED'
        }

if __name__ == '__main__':
    watchdog = DebugSessionWatchdog(session_timeout_ms=3000)
    print("=== Dynamic Debug Session Watchdog Timer Simulation ===")
    watchdog.start_session()
    print("OEM Engineer Authenticated: Debug Session Opened (3000 ms budget)")

    intervals = [1000, 1500, 1000]
    total_elapsed = 0
    for dt in intervals:
        total_elapsed += dt
        res = watchdog.tick_ms(dt)
        print(f"Elapsed: {total_elapsed:4d} ms -> Remaining: {res['time_left_ms']:4d} ms | Port Status: {res['status']}")
